import json
import os
import zipfile
from pathlib import Path
from pprint import pformat
from zipfile import ZIP_DEFLATED

import robot.api

from ..exception import EmptySuiteException
from ..utils.directories import Directories
from ..utils.encoder import BytesEncoder
from ..utils.logger import logger


class ReportCreator:
    """A class to create a zipped report for Reporting Portal."""

    def __init__(self, zip_name="reporting_portal.zip"):
        """
        :param string zip_name:  Name of the zip file with the report and the required files for Reporting Portal.
        """
        self._zip_name = zip_name

    def create_json_report_file(self, dst: str, collected) -> None:
        """Parse provided output.xml file and generate pkl report file for Reporting Portal.

        :param string dst: Path to directory where file should be stored.
        """
        logger.info("Creating report for Reporting Portal")
        json_data = collected.result
        json_path = f"{dst}/reporting_portal.json"
        with open(json_path, "w") as json_file:
            json.dump(json_data, json_file, cls=BytesEncoder)
        logger.debug(f"json file created: {json_path}")

    def zip_directory(self, src: str, dst: str) -> str:
        """ZIP a directory.

        :param string src: Path to directory to pack.
        :param string dst: Path to directory where zip should be stored.

        :return: Path to created file.
        :rtype: string
        """
        path_to_zip_file = os.path.join(dst, self._zip_name)
        with zipfile.ZipFile(
            path_to_zip_file, compression=ZIP_DEFLATED, mode="w"
        ) as zipf:
            for file_to_zip in os.listdir(src):
                zipf.write(os.path.join(src, file_to_zip), file_to_zip)

        logger.debug(f"ZIP file created: {path_to_zip_file}")

        return path_to_zip_file

    def _parse_results(self, output_path, collector, ignore_empty_suites):
        exec_result = robot.api.ExecutionResult(output_path)
        exec_result.visit(collector)
        if collector.result:
            return collector.result
        else:
            logger.warning("No suits/tests found. Check suite path.")
            self._suite_empty = True
            if ignore_empty_suites:
                logger.error(
                    "[FAIL] Report action was run on empty suite/non-existent suite."
                )
            else:
                raise EmptySuiteException(
                    "[FAIL] Report action was run on empty suite/non-existent suite."
                )

    def save_validation_result_to_file(self, configs, response):
        """
        :param    ConfigsStore    configs:    SconfigStore object containing configurations to that were validated
        :param    Response       response:    Response object of validation process
        """
        dirs = Directories(".")
        dirs.create_dir("validation_report")
        file_path = Path(dirs.dir_path) / "validation_report.txt"
        with file_path.open(mode="w") as report_file:
            report_file.write("Data sent:\n")
            for config in configs.to_dicts():
                report_file.write(f"{pformat(config, indent=4)}\n")
            report_file.write("\nValidation result:\n")
            for result in response:
                report_file.write(f"{pformat(result, indent=4)}\n")
